    const header=this._element('Група шапки','header')+this._element('Назва та іконка','brand')+this._element('Дата і поточний час','clock')+this._element('Рівень сигналу','signal')+this._ctrl('Зсув лінії','line_y','x',-40,40,.5,'%');
    const toggle=(label,key)=>`<div class="field effect-switch-row"><label>${this._ui(label)}</label><button class="toggle ${c[key]!==false?'on':''}" data-visibility-toggle="${key}" role="switch" aria-checked="${c[key]!==false}"><span></span><b>${c[key]!==false?this._ui('Увімкнено'):this._ui('Вимкнено')}</b></button></div>`;
    const weather=this._element('Група погоди','weather')+toggle('Показувати температуру на вулиці','outdoor_visible')+this._element('Температура на вулиці','outdoor')+toggle('Показувати вітер','wind_visible')+this._element('Вітер','wind')+toggle('Показувати опади','rain_visible')+this._element('Опади','rain')+this._field('Ентіті температури на вулиці','outdoor_temperature',c.outdoor_temperature,'sensor.outdoor_temperature')+this._field('Ентіті вітру','wind',c.wind,'sensor.wind')+this._field('Ентіті опадів','precipitation',c.precipitation,'sensor.precipitation');
