    const connection=this._element('Група підключення','connection')+this._element('Варіанти підключення','scheme')+`<div class="field"><label>Активна схема</label><div class="choices"><button data-choice="direct" class="${c.connection_mode==='direct'||!c.connection_mode?'active':''}">Прямий контакт</button><button data-choice="old" class="${c.connection_mode==='old'?'active':''}">Старий програматор</button><button data-choice="parallel" class="${c.connection_mode==='parallel'?'active':''}">Паралельно</button></div></div>`;
    const panel=this._element('Група нижньої панелі','panel')+this._element('Кнопки, іконки та написи','panel-buttons')+this._ctrl('Висота панелі','panel_h','x',-20,40,1,'%')+this._ctrl('Відстань між кнопками','panel_gap','x',0,20,.25,'%')+this._ctrl('Пропорції екрана','screen_aspect_ratio','s',1.2,2.5,.05,'');const effects=`<div class="field effect-switch-row"><label>Анімація під час роботи котла</label><button class="toggle ${c.effect_enabled!==false?'on':''}" data-effect-toggle role="switch" aria-checked="${c.effect_enabled!==false}"><span></span><b>${c.effect_enabled!==false?'Увімкнено':'Вимкнено'}</b></button></div>`+this._ctrl('Прозорість ефекту','effect_opacity','s',.1,1,.05,'')+this._element('Анімоване полум’я','effect');
    this.shadowRoot.innerHTML=`<style>:host{display:block;width:100%;max-width:100%;color:var(--primary-text-color);font-family:Arial,sans-serif}.editor{box-sizing:border-box;width:100%;padding:10px;border:1px solid var(--divider-color);border-radius:14px;background:linear-gradient(145deg,#18242a,#0b1216);box-shadow:0 8px 24px #0002}.editor-title{padding:7px 10px 12px;color:#ffae42;font-size:14px;font-weight:700;letter-spacing:1px}.accordion{margin:7px 0;border:1px solid #ffffff18;border-radius:10px;overflow:hidden;background:#ffffff05}.section-head{display:flex;width:100%;align-items:center;gap:10px;padding:13px 12px;border:0;background:linear-gradient(90deg,#152127,#0d1519);color:#cbd5df;text-align:left;cursor:pointer}.section-icon{width:22px;color:#ffae42;font-size:17px;text-align:center}.section-title{flex:1;font-size:12px;font-weight:700}.section-arrow{color:#ffae42;font-size:10px}.section-body{display:flex;flex-direction:column;gap:12px;padding:13px;background:#071014}.element{padding:10px;border:1px solid #ffffff14;border-radius:8px;background:#ffffff05}.element>b{display:block;margin-bottom:8px;color:#ffae42;font-size:11px}.field{display:grid;gap:5px}.field label{color:#b8c3cf;font-size:11px}input{box-sizing:border-box;width:100%;padding:8px;border:1px solid #ffffff22;border-radius:7px;background:#050b0e;color:#e6edf4;font:inherit;font-size:12px}.control-row{display:grid;gap:4px;margin:7px 0;color:#aebac6;font-size:10px}.control-line{display:grid;grid-template-columns:27px minmax(0,1fr) 27px 48px;gap:5px;align-items:center}.control-line button{height:25px;border:1px solid #ff941866;border-radius:6px;background:#ff941812;color:#ffae42;font-size:17px;cursor:pointer}.control-line input{padding:0;accent-color:#ff9418}.control-line strong{color:#ffae42;text-align:right;font-size:10px}.choices{display:flex;gap:6px;flex-wrap:wrap}.choices button{flex:1;min-width:90px;padding:9px 7px;border:1px solid #ffffff20;border-radius:7px;background:#ffffff08;color:#b9c4d0;font-size:11px}.choices button.active{border-color:#ff9418;color:#ffae42;background:#ff941815}.effect-switch-row{display:flex;align-items:center;justify-content:space-between;gap:10px}.toggle{display:inline-flex;align-items:center;gap:7px;border:1px solid #ffffff22;border-radius:999px;padding:4px 9px 4px 4px;background:#ffffff08;color:#9aa8b5;cursor:pointer;font-size:10px}.toggle span{width:20px;height:20px;border-radius:50%;background:#65727c;box-shadow:inset 0 1px #fff4}.toggle.on{border-color:#ff9418;color:#ffae42}.toggle.on span{background:#ff9418;box-shadow:0 0 8px #ff9418}ha-entity-picker{display:block;min-height:40px}@media(max-width:480px){.editor{padding:6px}.section-body{padding:10px}.control-line{grid-template-columns:24px minmax(0,1fr) 24px 42px}.choices button{min-width:75px;font-size:10px}}</style><div class="editor"><div class="editor-title">SMART HEATING — ${this._ui('Налаштування блоків')}</div>${this._section('device','◉','ПРИСТРІЙ',device+languageField)}${this._section('header','◒','ШАПКА',header)}${this._section('weather','☁','ПОГОДА',weather)}${this._section('climate','♨','КЛІМАТ',climate)}${this._section('connection','⌘','ПІДКЛЮЧЕННЯ',connection)}${this._section('panel','▣','ПАНЕЛЬ',panel)}${this._section('effects','✦','ВІЗУАЛЬНІ ЕФЕКТИ',effects)}</div>`;
